import DrylakeMark, { BRAND_INK, TILE_OCHRE, type BrandTone } from "@/components/brand/DrylakeMark";

/*
 * THE Drylake wordmark: the one implementation, used by the header, mobile menu, footer,
 * auth screens, client Workspace rail, Admin brand slot and the root error fallback.
 *
 * Geometry is the brand-kit wordmark, verbatim (public/brand/drylake-wordmark-*-bg.svg,
 * generated by drylake-ops/brand/logo-final/build_final.py from Outfit SemiBold): path one is
 * "Dr" + "lake" (filled with the surface ink), path two is the y, a stroked line whose tail
 * sweeps back under the word. Rule (Ben, 2026-10-07): the y is ALWAYS the tile ochre
 * (TILE_OCHRE); the other letters adapt to the surface (BRAND_INK).
 *
 * Inline SVG with fill/stroke attributes and inline sizing only, so it renders correctly even
 * where no stylesheet loaded (app/global-error.tsx). Ordinary words "Drylake" in copy are
 * text, never this component.
 */

export const WORDMARK_VIEWBOX = "-8.51 -85.84 414.22 129.01";
const VIEWBOX_W = 414.22;
const VIEWBOX_H = 129.01;
export const WORDMARK_ASPECT = VIEWBOX_W / VIEWBOX_H;

