/* The y as it sits in the wordmark: arms, then the tail sweeping back under "Dr". */
export const WORDMARK_Y_PATH =
  "M141.63,-46.04 L158.84,-1.42 M176.05,-46.04 L156.71,4.10 C153.61,12.13 146.51,20.49 138.00,20.49 C87.45,20.49 36.56,16.58 4.96,6.27";

/* The same y with a short tail: the version the closing CTA traces at large scale. */
export const WORDMARK_Y_TRACE_PATH =
  "M141.63,-46.04 L158.84,-1.42 M176.05,-46.04 L156.71,4.10 C153.61,12.13 146.51,20.49 138.00,20.49 C132.29,20.49 126.54,7.44 122.97,6.27";

export const WORDMARK_Y_STROKE = 14.18;

/*
 * The ochre y as an SVG fragment (draw in wordmark units; the caller's <svg>/<g> places it).
 * Every orange y on the site comes from here.
 */
export function WordmarkY({
  variant = "wordmark",
  opacity,
}: {
  variant?: "wordmark" | "trace";
  opacity?: number;
}) {
  return (
    <path
      d={variant === "trace" ? WORDMARK_Y_TRACE_PATH : WORDMARK_Y_PATH}
      fill="none"
      stroke={TILE_OCHRE}
      strokeWidth={WORDMARK_Y_STROKE}
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity={opacity}
    />
  );
}

export type DrylakeWordmarkProps = {
  /** Surface the wordmark sits on: "dark" = light letters, "light" = dark letters. */
  tone?: BrandTone;
  /** Rendered height of the wordmark in px (letters are about 62% of it; the y tail uses the rest). */
  height?: number;
  /** Show the cracked-tile mark to the left (the header/footer lockup). */
  lockup?: boolean;
  /** Colour the tile sits on (its cracks are drawn in it). Defaults per tone. */
  surface?: string;
  /** Accessible name. Pass null when a surrounding link already names it (decorative). */
  label?: string | null;
  className?: string;
  /** Extra classes for the tile (e.g. a hover rotation driven by a parent group). */
  markClassName?: string;
};

const DEFAULT_SURFACE: Record<BrandTone, string> = { dark: "#0b0b0a", light: "#ffffff" };

export default function DrylakeWordmark({
  tone = "dark",
  height = 24,
  lockup = false,
  surface,
  label = "Drylake",
  className,
  markClassName,
}: DrylakeWordmarkProps) {
  const width = Math.round(height * WORDMARK_ASPECT * 100) / 100;
  const a11y = label ? { role: "img", "aria-label": label } : { "aria-hidden": true as const };

  const word = (
    <svg
      viewBox={WORDMARK_VIEWBOX}
      width={width}
      height={height}
      focusable="false"
      data-drylake-wordmark={tone}
      style={{ display: "block", flexShrink: 0, overflow: "visible" }}
      {...(lockup ? { "aria-hidden": true as const } : a11y)}
      className={lockup ? undefined : className}
    >
      <path d={WORDMARK_LETTERS_PATH} fill={BRAND_INK[tone]} />
      <WordmarkY />
    </svg>
  );

  if (!lockup) {
    return word;
  }

  // Tile centred on the letters (not on the box, which also holds the y tail below them).
  const tile = Math.round(height * 0.82);
  const lettersCentre = height * ((85.84 - 39.2) / VIEWBOX_H);

  return (
    <span
      {...a11y}
      className={className}
      style={{ display: "inline-flex", alignItems: "flex-start", gap: Math.round(height * 0.32) }}
    >
      <DrylakeMark
        tone={tone}
        surface={surface ?? DEFAULT_SURFACE[tone]}
        className={markClassName}
        style={{
          width: tile,
          height: tile,
          flexShrink: 0,
          marginTop: Math.round(lettersCentre - tile / 2),
        }}
      />
      {word}
    </span>
  );
}
